var n=`0345-kartoffelsalat`;var o=`world-0345`;var i=`DE`;var a=`western-europe`;var s=4;var r=35;var l={en:`Kartoffelsalat`,ua:`Німецький картопляний салат`};var d={en:`A traditional Germany dish made with potato, bacon, yellow onion, white wine vinegar. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Німеччина. Основні інгредієнти: картопля, бекон, жовта цибуля, білий винний оцет. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var u=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`potato`,850,`g`],[`water`,1200,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`bacon`,190,`g`],[`yellow-onion`,170,`g`],[`sunflower-oil`,25,`ml`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:4,i:[[`beef-stock`,160,`ml`],[`white-wine-vinegar`,55,`ml`],[`dijon-mustard`,28,`g`],[`parsley`,23,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:n,id:o,country:`DE`,region:a,servings:4,minutes:35,title:l,text:d,steps:u};export{i as country,g as default,o as id,r as minutes,a as region,s as servings,n as slug,u as steps,d as text,l as title};